# ==== cell-state aware ILP (CNN parent/daughter probs -> edge prob adjustment + per-node division cost)
_cs_ps = REPO_DIR / "scripts" / "predict_unet_transformer.py"
_cs_s = _cs_ps.read_text()
_cs_helper = '\n# ---- cell-state aware ILP helpers (injected)\nimport os as _cs_os, glob as _cs_glob, types as _cs_types\nfrom pathlib import Path\nimport numpy as _cs_np\nimport zarr as _cs_zarr\n_CS_ALPHA = float(_cs_os.environ.get("BIOHUB_CS_ALPHA", "0.8"))\n_CS_BETA = float(_cs_os.environ.get("BIOHUB_CS_BETA", "0.0"))\n_CS_GAMMA = float(_cs_os.environ.get("BIOHUB_CS_GAMMA", "1.0"))\n_CS_DIVW = float(_cs_os.environ.get("BIOHUB_CS_DIVW", "1.2"))\n_CS_RHO = float(_cs_os.environ.get("BIOHUB_CS_RHO", "0.5"))\n_CS_SRC = \'"""3D cell-state classifier (continue / parent / daughter) on 3-frame patches. Small ResNet, self-contained\\n(this file is also embedded in the Kaggle notebook for inference).\\n\\ntrain:  python mitosis_cnn.py train --fold K --exclude names.txt --out runs/cnn_fK.pt   (K=-1 -> all data)\\n"""\\nimport argparse\\nimport json\\nimport sys\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport torch\\nimport torch.nn as nn\\nimport torch.nn.functional as F\\n\\nPZ, PY, PX = 7, 32, 32\\n\\n\\nclass Block(nn.Module):\\n    def __init__(self, cin, cout, stride=(1, 2, 2)):\\n        super().__init__()\\n        self.c1 = nn.Conv3d(cin, cout, 3, stride=stride, padding=1, bias=False)\\n        self.b1 = nn.BatchNorm3d(cout)\\n        self.c2 = nn.Conv3d(cout, cout, 3, padding=1, bias=False)\\n        self.b2 = nn.BatchNorm3d(cout)\\n        self.sc = nn.Sequential(nn.Conv3d(cin, cout, 1, stride=stride, bias=False), nn.BatchNorm3d(cout)) if (cin != cout or stride != (1, 1, 1)) else nn.Identity()\\n\\n    def forward(self, x):\\n        h = F.relu(self.b1(self.c1(x)))\\n        h = self.b2(self.c2(h))\\n        return F.relu(h + self.sc(x))\\n\\n\\nclass MitosisNet(nn.Module):\\n    def __init__(self, in_ch=3, width=24, n_cls=3):\\n        super().__init__()\\n        self.stem = nn.Sequential(nn.Conv3d(in_ch, width, 3, padding=1, bias=False), nn.BatchNorm3d(width), nn.ReLU())\\n        self.l1 = Block(width, width, (1, 1, 1))\\n        self.l2 = Block(width, width * 2, (1, 2, 2))\\n        self.l3 = Block(width * 2, width * 4, (2, 2, 2))\\n        self.l4 = Block(width * 4, width * 4, (1, 2, 2))\\n        self.head = nn.Linear(width * 4, n_cls)\\n\\n    def forward(self, x):\\n        x = self.l4(self.l3(self.l2(self.l1(self.stem(x)))))\\n        return self.head(x.mean((2, 3, 4)))\\n\\n\\ndef augment(x, rng):\\n    # x: (B,3,PZ,PY,PX) tensor on device\\n    if rng.random() < 0.5:\\n        x = x.flip(-1)\\n    if rng.random() < 0.5:\\n        x = x.flip(-2)\\n    if rng.random() < 0.5:\\n        x = x.transpose(-1, -2)\\n    if rng.random() < 0.5:\\n        x = x.flip(-3)\\n    scale = torch.tensor(rng.uniform(0.8, 1.25, size=(x.shape[0], 1, 1, 1, 1)), dtype=x.dtype, device=x.device)\\n    return x * scale\\n\\n\\n@torch.no_grad()\\ndef predict(model, X, device, bs=256, tta=True):\\n    model.eval()\\n    out = []\\n    for i in range(0, len(X), bs):\\n        xb = torch.as_tensor(np.asarray(X[i:i + bs], dtype=np.float32), device=device)\\n        logits = model(xb)\\n        if tta:\\n            logits = logits + model(xb.flip(-1)) + model(xb.flip(-2)) + model(xb.transpose(-1, -2))\\n            logits = logits / 4\\n        out.append(F.softmax(logits, 1).cpu().numpy())\\n    return np.concatenate(out)\\n\\n\\ndef train(a):\\n    d = np.load(Path(__file__).parent / "mitosis_patches.npz")\\n    X, y, soft, ds = d["X"], d["y"], d["soft"], d["ds"]\\n    excl = set(Path(a.exclude).read_text().split()) if a.exclude else set()\\n    m = ~np.isin(ds, list(excl))\\n    X, y, soft = X[m], y[m], soft[m]\\n    print("train patches", len(y), np.bincount(y), "excluded ds", len(excl), flush=True)\\n    device = torch.device("cuda")\\n    torch.manual_seed(a.seed)\\n    rng = np.random.default_rng(a.seed)\\n    model = MitosisNet().to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=1e-3, weight_decay=1e-4)\\n    sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=2e-3, total_steps=a.epochs * (len(y) // a.bs + 1))\\n    cw = torch.tensor([1.0, 4.0, 3.0], device=device)\\n    w_soft = torch.tensor(np.where(soft == 1, 0.5, 1.0), dtype=torch.float32)\\n    # oversample positives\\n    p = np.where(y == 0, 1.0, 6.0); p /= p.sum()\\n    for ep in range(a.epochs):\\n        model.train()\\n        idx = rng.choice(len(y), size=len(y), p=p)\\n        tot = 0\\n        for i in range(0, len(idx), a.bs):\\n            b = idx[i:i + a.bs]\\n            xb = torch.as_tensor(X[b].astype(np.float32), device=device)\\n            xb = augment(xb, rng)\\n            yb = torch.as_tensor(y[b], device=device)\\n            loss = (F.cross_entropy(model(xb), yb, weight=cw, reduction="none") * w_soft[b].to(device)).mean()\\n            opt.zero_grad(); loss.backward(); opt.step(); sched.step()\\n            tot += loss.item() * len(b)\\n        print(f"epoch {ep + 1}/{a.epochs} loss {tot / len(idx):.4f}", flush=True)\\n    out = Path(a.out); out.parent.mkdir(parents=True, exist_ok=True)\\n    torch.save({"state_dict": {k: v.half() for k, v in model.state_dict().items()}, "arch": "MitosisNet", "width": 24}, out)\\n    print("saved", out)\\n\\n\\ndef load_model(path, device):\\n    ck = torch.load(path, map_location=device)\\n    m = MitosisNet(width=ck.get("width", 24)).to(device)\\n    m.load_state_dict({k: v.float() for k, v in ck["state_dict"].items()})\\n    return m.eval()\\n\\n\\n\'\n_CS_MOD = _cs_types.ModuleType("mitosis_cnn"); exec(_CS_SRC, _CS_MOD.__dict__)\n_CS_MODEL = None\n_CS_DIVCOST = None\n_CS_PZ, _CS_PY, _CS_PX = 7, 32, 32\n\n\ndef _cs_load():\n    global _CS_MODEL\n    if _CS_MODEL is None:\n        cands = [c for c in _cs_glob.glob("/kaggle/input/**/cnn_all.pt", recursive=True) if "biohub-divclf3-weights" in c]\n        if not cands:\n            raise FileNotFoundError("cnn_all.pt not found for biohub-divclf3-weights")\n        _CS_MODEL = _CS_MOD.load_model(cands[0], torch.device("cuda" if torch.cuda.is_available() else "cpu"))\n    return _CS_MODEL\n\n\ndef _cs_probs(coords, ds_path):\n    """CNN probs (N,3) for coords [t,z,y,x] in original voxels."""\n    ds_path = Path(ds_path)\n    if not (ds_path / "0").exists():\n        ds_path = ds_path.with_name(ds_path.name + ".zarr")\n    g = _cs_zarr.open_group(str(ds_path), mode="r")\n    q = dict(g.attrs)["image_statistics"]["quantiles"]\n    lo, hi = q["0.01"], q["0.999"]\n    img = _cs_zarr.open_array(str(ds_path / "0"), mode="r")\n    T = img.shape[0]\n    model = _cs_load()\n    dev = next(model.parameters()).device\n    import time as _cs_time; _cs_t0 = _cs_time.time()\n    order = _cs_np.argsort(coords[:, 0], kind="stable")\n    out = _cs_np.zeros((len(coords), 3), _cs_np.float32)\n    cache = {}\n    def fr(t):\n        t = min(max(int(t), 0), T - 1)\n        if t not in cache:\n            if len(cache) > 4:\n                cache.pop(next(iter(cache)))\n            cache[t] = img[t]\n        return cache[t]\n    bs = 2048\n    X = _cs_np.zeros((bs, 3, _CS_PZ, _CS_PY, _CS_PX), _cs_np.float32); idx = []\n    _use_amp = dev.type == "cuda"\n    def flush():\n        if not idx:\n            return\n        with torch.no_grad(), torch.autocast(device_type="cuda", dtype=torch.float16, enabled=_use_amp):\n            xb = torch.as_tensor(X[:len(idx)], device=dev)\n            pr = torch.softmax(model(xb).float(), 1).cpu().numpy()\n        out[idx] = pr; idx.clear()\n    for i in order:\n        t, z, y, x = [int(v) for v in coords[i]]\n        k = len(idx)\n        X[k] = 0\n        for j, tt in enumerate((t - 1, t, t + 1)):\n            v = fr(tt)\n            z0, y0, x0 = z - _CS_PZ // 2, y - _CS_PY // 2, x - _CS_PX // 2\n            zs = slice(max(z0, 0), min(z0 + _CS_PZ, v.shape[0])); ys = slice(max(y0, 0), min(y0 + _CS_PY, v.shape[1])); xs = slice(max(x0, 0), min(x0 + _CS_PX, v.shape[2]))\n            X[k, j, zs.start - z0:zs.stop - z0, ys.start - y0:ys.stop - y0, xs.start - x0:xs.stop - x0] = (v[zs, ys, xs].astype(_cs_np.float32) - lo) / (hi - lo)\n        idx.append(i)\n        if len(idx) == bs:\n            flush()\n    flush()\n    print(f"CSILP cnn pass {ds_path.stem}: {len(coords)} coords in {_cs_time.time() - _cs_t0:.1f}s", flush=True)\n    return out\n\n\ndef _cs_adjust(coords, edges, ds_path):\n    """edges: list of (src, tgt, prob, dist). Returns adjusted list; sets _CS_DIVCOST per coords row."""\n    global _CS_DIVCOST\n    _CS_DIVCOST = None\n    try:\n        pr = _cs_probs(_cs_np.asarray(coords), ds_path)\n        p_par, p_dau = pr[:, 1].astype(float), pr[:, 2].astype(float)\n        _CS_DIVCOST = _CS_DIVW * (1.0 - p_par) ** _CS_GAMMA - _CS_RHO * p_par\n        out = []; n_mod = 0\n        for s, t, p, d in edges:\n            p2 = p * (1.0 - _CS_BETA * p_dau[t] * (1.0 - p_par[s])) + _CS_ALPHA * p_par[s] * p_dau[t]\n            p2 = min(max(p2, 0.0), 1.0)\n            n_mod += abs(p2 - p) > 0.05\n            out.append((s, t, p2, d))\n        print(f"CSILP {ds_path.stem}: coords={len(coords)} edges={len(edges)} modified={n_mod} p_par>0.3={int((p_par > 0.3).sum())}", flush=True)\n        return out\n    except Exception as e:\n        import traceback; traceback.print_exc()\n        print("CSILP FAILED (unchanged edges):", type(e).__name__, e, flush=True)\n        _CS_DIVCOST = None\n        return edges\n\n'
_cs_reps = [
    ("import tracksdata as td\n", "import tracksdata as td\n" + "# CSILP_HELPER_BELOW\n"),
    ("        graph = build_graph(coords, edges)\n", "        edges = _cs_adjust(coords, edges, ds_path)\n        graph = build_graph(coords, edges)\n"),
    ("    node_ids = graph.bulk_add_nodes([\n        {\"t\": int(t), \"z\": float(z), \"y\": float(y), \"x\": float(x)}\n        for t, z, y, x in coords\n    ])\n",
     "    graph.add_node_attr_key(\"div_cost\", pl.Float64, float(_cs_os.environ.get(\"BIOHUB_CS_DIVW\", \"1.2\")))\n    _dc = _CS_DIVCOST if (_CS_DIVCOST is not None and len(_CS_DIVCOST) == len(coords)) else [float(_cs_os.environ.get(\"BIOHUB_CS_DIVW\", \"1.2\"))] * len(coords)\n    node_ids = graph.bulk_add_nodes([\n        {\"t\": int(t), \"z\": float(z), \"y\": float(y), \"x\": float(x), \"div_cost\": float(dc)}\n        for (t, z, y, x), dc in zip(coords, _dc)\n    ])\n"),
    ("        ilp_division_weight=args.ilp_division_weight,\n", "        ilp_division_weight=\"div_cost\",  # per-node division cost attr (CSILP)\n"),
]
for _old, _new in _cs_reps:
    if _cs_s.count(_old) != 1:
        raise RuntimeError(f"CSILP anchor count {_cs_s.count(_old)} for: {_old[:60]!r}")
    _cs_s = _cs_s.replace(_old, _new, 1)
# helper must come after the script's own imports (torch, np, pl) -> append right after the import block marker
_cs_s = _cs_s.replace("# CSILP_HELPER_BELOW\n", "", 1)
_cs_marker = "def build_graph("
assert _cs_s.count(_cs_marker) == 1
_cs_s = _cs_s.replace(_cs_marker, _cs_helper + "\n\n" + _cs_marker, 1)
compile(_cs_s, str(_cs_ps), "exec")
_cs_ps.write_text(_cs_s)
print("CSILP patch installed: alpha/beta/gamma/divw =", os.environ.get("BIOHUB_CS_ALPHA", "0.8"), os.environ.get("BIOHUB_CS_BETA", "0.0"), os.environ.get("BIOHUB_CS_GAMMA", "1.0"), os.environ.get("BIOHUB_CS_DIVW", "1.2"), flush=True)
